      for (let i = 0; i < 6; i++) { s += P(`M${72 + i * 5} 64 l${-6 + i * 2} 18`, DGRAY, 2) + P(`M${222 + i * 5} 64 l${-4 + i * 2} 18`, DGRAY, 2); }
      s += P('M158 64 l0 10', DGRAY, 2) + lab(60, 18, 80, 30, '극') + lab(260, 18, 240, 30, '극') + T(160, 100, '클립이 양 끝(극)에 많이 붙어요', { s: 12, c: MU });
      s += mag(25, 135, 'N', 'S', 60, 26) + Ln(85, 125, 85, 172, HI, 2, DASH) + T(85, 190, '반으로 자르면', { s: 12, c: MU }) +
        ar(170, 148, 200, 148, AC, 2) + mag(210, 135, 'N', 'S', 22, 26) + mag(262, 135, 'N', 'S', 22, 26) + T(260, 190, '조각마다 N극·S극', { s: 12, c: MU });
      return S('막대자석의 양 끝에 클립이 많이 붙고, 자석을 잘라도 조각마다 N극과 S극이 생기는 모습', s);
