      s += R(160 - 3, 30, 6, 90, RED) + T(160, 22, '해령', { s: 12, b: 1, c: RED }) + ar(150, 136, 80, 136, AC, 2) + ar(170, 136, 240, 136, AC, 2) + T(160, 156, '해령에서 멀수록 나이가 많고 퇴적물이 두꺼움', { s: 12 });
      s += P('M10 186 L150 172 L160 170 L170 172 L310 186 Z', 'none', 0, '#d6a86a') + T(160, 198, '고지자기 줄무늬가 해령을 축으로 대칭', { s: 12, c: MU }) + T(60, 60, '■ 정자극기', { s: 12, a: 'end' }) + T(300, 60, '□ 역자극기', { s: 12, a: 'end' });
